input_schema:
Combined findings from all prior stages
{
  "code_diff": "string - Original code changes",
  "static_analysis": "object - Output from Stage 1",
  "security_review": "object - Output from Stage 2",
  "pr_metadata": {
    "title": "string",
    "author": "string",
    "branch": "string",
    "description": "string | null"
  }
}

output_schema:
Final review report with prioritized findings and approval recommendation
{
  "review_summary": {
    "pr_title": "string",
    "author": "string",
    "lines_changed": "number",
    "files_affected": "number",
    "review_verdict": "approve | request_changes | comment",
    "confidence": "high | medium | low"
  },
  "critical_issues": [
    {
      "id": "string",
      "source": "static | security",
      "title": "string",
      "description": "string",
      "location": "string",
      "action_required": "string",
      "suggested_fix": "string"
    }
  ],
  "major_issues": [
    {
      "id": "string",
      "source": "static | security",
      "title": "string",
      "description": "string",
      "location": "string",
      "recommendation": "string"
    }
  ],
  "minor_issues": [
    {
      "id": "string",
      "title": "string",
      "description": "string",
      "location": "string",
      "suggestion": "string"
    }
  ],
  "nitpicks": [
    {
      "location": "string",
      "comment": "string"
    }
  ],
  "positive_observations": [
    {
      "aspect": "string",
      "comment": "string"
    }
  ],
  "action_items": {
    "must_fix_before_merge": ["string"],
    "should_fix_before_merge": ["string"],
    "consider_for_future": ["string"],
    "follow_up_tickets": ["string"]
  },
  "review_comment": "string - Overall comment to post on PR"
}
